      "most_likely_effort": 1
    },
    {
      "activity_id": "A1.2",
      "activity_name": "Implement friendly name in lifecycle system chaincode",
      "activity_description": "Add storage, retrieval, and validation of friendly name in the lifecycle system chaincode.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A1.3",
      "activity_name": "Update CLI for friendly name support",
      "activity_description": "Modify peer CLI commands (deploy, query, etc.) to accept and display friendly name.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A1.4",
      "activity_name": "Unit and integration tests for friendly name",
      "activity_description": "Write tests covering friendly name functionality in lifecycle chaincode and CLI.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2.1",
