      "activity_name": "Implement state cache in peer",
      "activity_description": "Implement cache data structures and APIs in peer codebase.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A6.3",
      "activity_name": "Integrate state cache with transaction simulation",
      "activity_description": "Modify transaction simulator to use cache for read operations during rw-set building.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6.4",
      "activity_name": "Unit and integration tests for state cache",
      "activity_description": "Test cache correctness, eviction, concurrency, and performance impact.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7.1",
      "activity_name": "Restructure documentation for hyperledger.org",
      "activity_description": "Reorganize existing documentation into logical sections for hyperledger.org publishing.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7.2",
      "activity_name": "Set up hosting and publishing pipeline",
      "activity_description": "Configure static site generator (Hugo) and deployment pipeline to hyperledger.org.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A7.3",
      "activity_name": "Verify and update links",
      "activity_description": "Check all links, fix broken ones, and ensure search/indexing works.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A8.1",
      "activity_name": "Design CLI separation",
      "activity_description": "Identify CLI commands, dependencies, and plan extraction from peer codebase.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A8.2",
      "activity_name": "Refactor CLI code out of peer",
      "activity_description": "Move CLI command implementations to separate module, remove RocksDB dependency.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A8.3",
      "activity_name": "Build separate CLI binary",
      "activity_description": "Create main package for CLI, configure Go build for cross-compilation.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A8.4",
      "activity_name": "Packaging for Mac, Windows, Linux",
      "activity_description": "Create installers/tarballs for each platform, test installation.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A8.5",
      "activity_name": "Update documentation for CLI installation",
      "activity_description": "Write installation instructions for new standalone CLI binary.",
