    },
    {
      "activity_id": "A8.6",
      "activity_name": "Unit and integration tests for CLI",
      "activity_description": "Test CLI commands against peer and orderer, verify no RocksDB dependency.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 69
  }
}

